inline const Def* find(int id) { return id >= 0 && id < kCount ? &kItems[id] : nullptr; }
inline const char* name(int id) { const Def* d = find(id); return d ? d->name : "?"; }
inline bool in_case(int id) { const Def* d = find(id); return d && d->w; }

// Whether an item's cItem keeps a state of its own - upgrade levels (+6) and
// loaded rounds (+8): the weapons, which a new entry's set-up (FUN_00707780)
// gives a levels word and a full magazine. Any other item's +6 and +8 hold
// what the entry's last occupant left there (a part's are the weapon it is
// attached to, a file's its place in the list): no state of the item's own.
inline bool keeps_state(int id) { const Def* d = find(id); return d && d->state; }

// The attache case's sizes S, M, L, XL: items to the game, but the size of the
// case is which of them is held (the sub-screen's set-up, FUN_007690C0, sets
// SubScreenWk+2AA by it) - the case's own state, not an item to add or remove.
inline constexpr short kCaseIds[4] = {124, 125, 126, 127};
inline bool is_case(int id) { return id >= kCaseIds[0] && id <= kCaseIds[3]; }

// itemInfo's counts for a kind: how many one pickup gives (def) and how many
// one slot or entry holds (max), by difficulty (+847C: Amateur below 2, Easy
// below 4). Weapons and parts are one each; treasures and gems stack to 999.
struct Counts {
  int type, def, max;
};
inline Counts counts(int kind, int difficulty) {
  const bool amateur = difficulty < 2, easy = difficulty < 4;
  switch (kind) {
    case 0: return amateur ? Counts{2, 10, 20} : Counts{2, 5, 10};
    case 1: return {3, 1, 1};
    case 2: return {1, 0, 0};
    case 3: return amateur ? Counts{2, 20, 150} : Counts{2, 10, 50};
    case 4: return {6, 1, 1};
    case 5: return {2, amateur ? 10 : 5, easy ? 20 : 10};
    case 6: return {1, 0, 0};
    case 7: return amateur ? Counts{2, 10, 40} : Counts{2, 5, 20};
    case 8: return amateur ? Counts{2, 20, 50} : Counts{2, 10, easy ? 25 : 15};
    case 9: return amateur ? Counts{2, 20, 20} : Counts{2, 10, 10};
    case 10: return amateur ? Counts{2, 100, 200} : Counts{2, 50, 100};
    case 11: return {9, 0, 0};
    case 12: return {2, amateur ? 2 : 1, easy ? 10 : 5};
    case 13: return {10, 1, 1};
    case 14: return {11, 1, 1};
    case 15: return {12, 1, 999};
    case 16: return {5, 1, 999};
    case 17: return amateur ? Counts{2, 100, 200} : Counts{2, 50, 100};
    case 18: return {8, 5, 999};
    case 19: return amateur ? Counts{2, 10, 40} : Counts{2, 5, 20};
    case 20: return {8, 30, 999};
    case 21: return {5, 1, 1};
    case 22: return {13, 1, 1};
    default: return {7, 1, 1};
  }
}

// The upgrade a weapon's exclusive tune-up adds beyond its normal maximum, per
// stat (firepower, firing speed, reload speed, capacity): the merchant's
// Exclusive upgrade is one more level of these. The weapon's levels word holds
// level - 1 in four nibbles.
struct Exclusive {
  short id;
  unsigned char extra[4];
};
inline constexpr Exclusive kExclusive[] = {
    {47, {0, 1, 0, 0}},  // Rifle (semi-auto)
    {48, {1, 0, 0, 0}},  // TMP
    {148, {1, 0, 0, 0}},  // Riot Gun
    {3, {0, 0, 0, 1}},  // Matilda
    {45, {0, 0, 0, 1}},  // Striker
    {46, {1, 0, 0, 0}},  // Rifle
    {39, {1, 0, 0, 0}},  // Blacktail
    {37, {1, 0, 0, 0}},  // Red9
    {41, {1, 0, 0, 0}},  // Broken Butterfly
    {54, {1, 0, 0, 0}},  // Mine Thrower
    {35, {1, 0, 0, 0}},  // Handgun
    {44, {1, 0, 0, 0}},  // Shotgun
    {33, {1, 0, 0, 0}},  // Punisher
    {55, {1, 0, 0, 1}},  // Handcannon
    {52, {1, 0, 0, 1}},  // Chicago Typewriter
    {83, {1, 0, 0, 1}},  // Chicago Typewriter (Ada)
};
inline int exclusive(int id, int stat) {
  for (const Exclusive& e : kExclusive)
    if (e.id == id) return e.extra[stat];
  return 0;
}

